import React, { useRef, useEffect, useCallback } from 'react';
import { motion, useScroll, useSpring, useMotionValueEvent } from 'framer-motion';

export default function GraduationScene() {
  const containerRef = useRef(null);
  const videoRef     = useRef(null);
  const canvasRef    = useRef(null);
  const rafRef       = useRef(null);
  const durationRef  = useRef(10);
  const isSeeking    = useRef(false);

  // ── Draw current video frame to canvas every rAF tick ──────────────────
  const startRenderLoop = useCallback(() => {
    const video  = videoRef.current;
    const canvas = canvasRef.current;
    if (!video || !canvas) return;
    const ctx = canvas.getContext('2d');

    const draw = () => {
      if (video.readyState >= 2) {
        // Draw at CSS pixel dimensions (no dpr scaling on video — not needed)
        ctx.drawImage(video, 0, 0, canvas.width, canvas.height);
      }
      rafRef.current = requestAnimationFrame(draw);
    };
    rafRef.current = requestAnimationFrame(draw);
  }, []);

  // ── Video + Canvas setup ────────────────────────────────────────────────
  useEffect(() => {
    const video  = videoRef.current;
    const canvas = canvasRef.current;
    if (!video || !canvas) return;

    // Simple sizing — match viewport, no dpr scaling
    const syncSize = () => {
      canvas.width  = window.innerWidth;
      canvas.height = window.innerHeight;
    };
    syncSize();
    window.addEventListener('resize', syncSize);

    const onMeta = () => { durationRef.current = video.duration || 10; };
    if (video.readyState >= 1) onMeta();
    else video.addEventListener('loadedmetadata', onMeta);

    // Prime decoder so fastSeek works instantly
    const prime = async () => {
      try {
        video.muted = true;
        video.currentTime = 0;
        await video.play();
        setTimeout(() => {
          video.pause();
          video.currentTime = 0;
          startRenderLoop();
        }, 150);
      } catch (_) {
        video.currentTime = 0.001;
        startRenderLoop();
      }
    };
    prime();

    return () => {
      video.removeEventListener('loadedmetadata', onMeta);
      window.removeEventListener('resize', syncSize);
      if (rafRef.current) cancelAnimationFrame(rafRef.current);
    };
  }, [startRenderLoop]);

  // ── Scroll → video currentTime (SMOOTHED) ───────────────────────────
  const { scrollYProgress } = useScroll({ target: containerRef, offset: ['start start', 'end end'] });

  // Spring artificially smooths out discrete/chunky external mouse wheel events,
  // making them behave exactly like a continuous trackpad scroll.
  const smoothProgress = useSpring(scrollYProgress, { damping: 25, stiffness: 120, mass: 0.5 });
  const latestTimeRef = useRef(0);

  const seekToLatest = useCallback(() => {
    const video = videoRef.current;
    if (!video) return;

    const targetT = latestTimeRef.current;
    isSeeking.current = true;

    requestAnimationFrame(() => {
      if (!videoRef.current) return;

      const onSeeked = () => {
        // If the user kept scrolling while we were seeking, immediately seek again to catch up
        if (Math.abs(latestTimeRef.current - videoRef.current.currentTime) > 0.05) {
          seekToLatest();
        } else {
          isSeeking.current = false;
        }
      };

      videoRef.current.addEventListener('seeked', onSeeked, { once: true });

      if (typeof videoRef.current.fastSeek === 'function') {
        videoRef.current.fastSeek(targetT);
      } else {
        videoRef.current.currentTime = targetT;
      }
    });
  }, []);

  useMotionValueEvent(smoothProgress, 'change', (latest) => {
    latestTimeRef.current = latest * durationRef.current;
    if (!isSeeking.current) {
      seekToLatest();
    }
  });

  return (
    <div
      ref={containerRef}
      className="graduation-outer"
      style={{ position: 'relative', height: '300vh', background: '#010103', zIndex: 10 }}
    >
      {/* Sticky full-screen panel */}
      <div
        className="graduation-sticky"
        style={{
          position: 'sticky', top: 0,
          width: '100%', height: '100vh',
          overflow: 'hidden',
        }}>

        {/* Canvas fills the entire viewport */}
        <canvas
          ref={canvasRef}
          style={{
            position: 'absolute', inset: 0,
            width: '100%', height: '100%',
            filter: 'contrast(1.15) saturate(1.1)',
            display: 'block',
          }}
