      if (rafRef.current) cancelAnimationFrame(rafRef.current);
    };
  }, [startRenderLoop]);

  // ── Scroll → video currentTime ──────────────────────────────────────────
  useEffect(() => {
    const onScroll = () => {
      const container = containerRef.current;
      const video     = videoRef.current;
      if (!container || !video) return;

      const rect       = container.getBoundingClientRect();
      const scrollable = container.offsetHeight - window.innerHeight; // 200vh scroll
      const scrolled   = Math.max(0, Math.min(scrollable, -rect.top));
      const progress   = scrolled / scrollable;
      const t          = progress * durationRef.current;

      if (!isSeeking.current) {
        isSeeking.current = true;
        requestAnimationFrame(() => {
          if (!videoRef.current) return;
          if (typeof videoRef.current.fastSeek === 'function') {
            videoRef.current.fastSeek(t);
          } else {
            videoRef.current.currentTime = t;
          }
          const onSeeked = () => {
            isSeeking.current = false;
            videoRef.current.removeEventListener('seeked', onSeeked);
          };
          videoRef.current.addEventListener('seeked', onSeeked);
        });
      }
    };

    window.addEventListener('scroll', onScroll, { passive: true });
    onScroll();
    return () => window.removeEventListener('scroll', onScroll);
  }, []);

  return (
    <div
      ref={containerRef}
      className="graduation-outer"
      style={{
        position: 'relative',
        height: '300vh',
        width: '100%',
        background: '#010103',
