        }} />

        {/* ── Centered text overlay ── */}
        <div style={{
          position: 'absolute', inset: 0,
          display: 'flex', flexDirection: 'column',
          alignItems: 'center', justifyContent: 'center',
          textAlign: 'center', zIndex: 10,
          padding: '0 20px',
          pointerEvents: 'none'
        }}
        >
          <motion.div
            initial={{ opacity: 0, scale: 0.9, y: 30 }}
            whileInView={{ opacity: 1, scale: 1, y: 0 }}
            viewport={{ once: true, margin: '-20%' }}
            transition={{ duration: 1.5, ease: 'easeOut' }}
          >
            <h2 style={{
              fontFamily: 'var(--font-serif)', fontSize: 'clamp(3rem, 7vw, 6.5rem)', color: '#fff',
              margin: 0, lineHeight: 1.05, textShadow: '0 20px 40px rgba(0,0,0,0.8)'
            }}>
              From First Step to<br />
              <span style={{
                color: 'var(--accent-gold)', fontStyle: 'italic',
                background: 'linear-gradient(90deg, #fff, var(--accent-gold))',
                WebkitBackgroundClip: 'text', WebkitTextFillColor: 'transparent',
                filter: 'drop-shadow(0 0 40px rgba(249,212,64,0.3))'
              }}>
                Final Capstone.
              </span>
