            <p style={{
              fontFamily: 'var(--font-sans)', fontSize: '1.2rem', color: 'rgba(255,255,255,0.8)',
              maxWidth: '600px', margin: '30px auto 0', lineHeight: 1.7, fontWeight: 300,
              textShadow: '0 4px 20px rgba(0,0,0,0.8)'
            }}>
              We don't just secure your admission. We engineer the trajectory of your entire career. Welcome to the elite global network.
            </p>

            <motion.a
              href="/contact"
              className="graduation-cta-btn"
              whileHover={{ scale: 1.05, boxShadow: '0 0 50px rgba(249,212,64,0.35)' }}
              whileTap={{ scale: 0.97 }}
              style={{
                marginTop: 40, display: 'inline-block',
                padding: '16px 48px', borderRadius: '100px',
                border: '1.5px solid rgba(249,212,64,0.6)',
                color: 'var(--accent-gold)', fontSize: '0.85rem',
                fontWeight: 700, letterSpacing: 3, textTransform: 'uppercase',
                textDecoration: 'none', backdropFilter: 'blur(10px)',
                background: 'rgba(2,2,5,0.7)', pointerEvents: 'auto'
